class Solution {
public:
    int maximumUnits(vector<vector<int>>& boxTypes, int truckSize) {
        int bucket[1001] = {0};
        for (auto& b : boxTypes) {
            bucket[b[1]] += b[0];
        }
        int total = 0;
        for (int u = 1000; u >= 1 && truckSize > 0; --u) {
            int take = min(bucket[u], truckSize);
            total += take * u;
            truckSize -= take;
        }
        return total;
    }
};
